import { useEffect, useMemo, useState } from "react";
import { AlertTriangle, Archive, ArrowLeft, Bell, BriefcaseBusiness, Building2, Check, ChevronRight, CircleHelp, ClipboardList, Clock3, FileCheck2, FileText, GitPullRequest, Image, LayoutDashboard, LogOut, Menu, Plus, Search, Settings, UserPlus, UserRound, Users, X } from "lucide-react";
import { Audit, departments, projects, seedProjects, seedTasks, seedAudit, seedNotices, seedWeeklyObjectives, seedStaffStatuses, Project, Task, User, users, Notice, AccessRole, EmploymentType, AccountStatus, WeeklyObjective, ObjectiveStatus, StaffStatus, Availability } from "./data";

type View="Overview"|"Tasks"|"Projects"|"People"|"Blockers"|"Weekly Review"|"Departments"|"Integrations"|"Audit Log"|"Settings"|"Notifications";
const navGroups:{label:string;items:{name:View;icon:any}[]}[]=[
  {label:"Work",items:[{name:"Overview",icon:LayoutDashboard},{name:"Tasks",icon:ClipboardList},{name:"Projects",icon:BriefcaseBusiness}]},
  {label:"Team",items:[{name:"People",icon:Users},{name:"Departments",icon:Building2},{name:"Blockers",icon:AlertTriangle}]},
  {label:"Cadence",items:[{name:"Weekly Review",icon:FileCheck2}]}];
const initials=(n:string)=>n.split(" ").map(x=>x[0]).join("").slice(0,2).toUpperCase();
const accessOf=(person:User):AccessRole=>person.accessRole||(person.role==="Super Admin"?"Superadmin":person.role==="Manager"?"Manager":"Member");
const employmentOf=(person:User):EmploymentType=>person.employmentType||(person.role==="Intern"?"Intern":"Employee");
const accountOf=(person:User):AccountStatus=>person.accountStatus||(person.active===false?"Suspended":"Active");
const isAdmin=(person:User)=>["Superadmin","Admin"].includes(accessOf(person));
const isManager=(person:User)=>accessOf(person)==="Manager";
function Avatar({person,size=30}:{person?:User;size?:number}){return person?.avatarUrl?<img className="avatar avatar-image" src={person.avatarUrl} alt={`${person.name}'s profile`} style={{width:size,height:size}}/>:<div className="avatar avatar-placeholder" style={{width:size,height:size}} aria-label={`${person?.name||"Team member"} profile placeholder`}><UserRound size={Math.max(14,Math.round(size*.48))} strokeWidth={1.7}/></div>}
function ProjectLogo({project,size=44}:{project:Project;size?:number}){return project.logoUrl?<img className="project-logo" src={project.logoUrl} alt={`${project.name} logo`} style={{width:size,height:size}}/>:<div className="project-logo project-logo-fallback" style={{width:size,height:size}} aria-label={`${project.name} logo fallback`}>{initials(project.name)}</div>}
function AvatarStack({people}:{people:User[]}){return <div className="avatar-stack" aria-label={`${people.length} assigned people`}>{people.slice(0,4).map((person,index)=><span key={person.id} style={{zIndex:4-index}}><Avatar person={person} size={25}/></span>)}{people.length>4&&<span className="avatar-more">+{people.length-4}</span>}</div>}
function useStore<T>(key:string, initial:T){const [value,setValue]=useState<T>(()=>{try{return JSON.parse(localStorage.getItem(key)||"null")??initial}catch{return initial}});useEffect(()=>localStorage.setItem(key,JSON.stringify(value)),[key,value]);return [value,setValue] as const}

export default function App(){
  const [user,setUser]=useState<User|null>(null); const [view,setView]=useState<View>("Overview"); const [taskId,setTaskId]=useState<string|null>(null); const [projectId,setProjectId]=useState<string|null>(null); const [searchQuery,setSearchQuery]=useState("");
  const [loading,setLoading]=useState(false);
   const [tasks,setTasks]=useStore<Task[]>("olyxee-tasks",seedTasks); const [projectsData,setProjectsData]=useStore<Project[]>("olyxee-projects",seedProjects); const [audit,setAudit]=useStore<Audit[]>("olyxee-audit",seedAudit); const [notices,setNotices]=useStore<Notice[]>("olyxee-notices",seedNotices); const [team,setTeam]=useStore<User[]>("olyxee-team",users); const [objectives,setObjectives]=useStore<WeeklyObjective[]>("olyxee-weekly-objectives",seedWeeklyObjectives); const [staffStatuses,setStaffStatuses]=useStore<StaffStatus[]>("olyxee-staff-statuses",seedStaffStatuses);
  const [notice,setNotice]=useState(""); const [modal,setModal]=useState<"task"|"person"|"blocker"|"project"|"objective"|null>(null); const [editingPerson,setEditingPerson]=useState<User|undefined>(); const [profileOpen,setProfileOpen]=useState(false); const [notificationsOpen,setNotificationsOpen]=useState(false); const [settingsOpen,setSettingsOpen]=useState(false);
  const active=team.find(person=>person.id===user?.id)||user||users[0]; const activeStatus=staffStatuses.find(status=>status.userId===active.id); const activeNotices=notices.filter(item=>item.userId===active.id); const can=(action:string)=>isAdmin(active)||(isManager(active)&&["task","review","person"].includes(action));
  const allowed:View[]=accessOf(active)==="Member"?["Tasks","Projects","Notifications","Settings"]:isManager(active)?["Overview","Tasks","Projects","People","Blockers","Weekly Review","Departments","Notifications","Settings"]:["Overview","Projects","People","Departments","Blockers","Weekly Review","Notifications","Settings"];
  const visibleView=allowed.includes(view)?view:(accessOf(active)==="Member"?"Tasks":"Overview");
  const visibleTasks=isAdmin(active)?tasks:isManager(active)?tasks.filter(t=>t.department===active.department):tasks.filter(t=>t.assignee===active.id||t.available);
  const searchResults=useMemo(()=>{
    const query=searchQuery.trim().toLowerCase(); if(!query)return [];
    const words=query.split(/\s+/); const matches=(text:string)=>words.every(word=>text.toLowerCase().includes(word));
    const scopedPeople=team.filter(person=>isAdmin(active)||person.id===active.id||person.reportsTo===active.id);
    const scopedProjects=projectsData.filter(project=>isAdmin(active)||project.assigneeIds.includes(active.id));
    const results:{id:string;label:string;meta:string;kind:"view"|"task"|"project";target:string}[]=[];
    allowed.forEach(item=>{if(matches(`${item} page navigation`))results.push({id:`view-${item}`,label:item,meta:"Navigation",kind:"view",target:item})});
    visibleTasks.forEach(task=>{if(matches(`${task.id} ${task.title} ${task.project} ${task.status} ${task.priority} ${task.description}`))results.push({id:`task-${task.id}`,label:task.title,meta:`${task.id} · ${task.project} · ${task.status}`,kind:"task",target:task.id})});
    scopedProjects.forEach(project=>{if(matches(`${project.name} ${project.description} ${project.status}`))results.push({id:`project-${project.id}`,label:project.name,meta:"Project",kind:"project",target:project.id})});
    scopedPeople.forEach(person=>{if(matches(`${person.name} ${person.email} ${person.department} ${employmentOf(person)} ${accessOf(person)} ${accountOf(person)}`))results.push({id:`person-${person.id}`,label:person.name,meta:`${employmentOf(person)} · ${accessOf(person)} · ${person.department}`,kind:"view",target:"People"})});
    departments.filter(department=>isAdmin(active)||department[0]===active.department).forEach(department=>{if(matches(department.join(" ")))results.push({id:`department-${department[0]}`,label:department[0],meta:`Department · ${department[1]}`,kind:"view",target:"Departments"})});
    objectives.filter(objective=>isAdmin(active)||objective.managerId===active.id).forEach(objective=>{if(matches(`${objective.title} ${objective.description} ${objective.priority} ${objective.status}`))results.push({id:`objective-${objective.id}`,label:objective.title,meta:`Weekly objective · ${objective.status}`,kind:"view",target:"Weekly Review"})});
    return results.slice(0,8);
  },[searchQuery,allowed,visibleTasks,team,projectsData,objectives,active]);
 const log=(action:string)=>setAudit(a=>[{id:crypto.randomUUID(),actor:active.name,action,time:"Just now"},...a]);
 const notify=(userId:string,title:string,body:string)=>setNotices(n=>[{id:crypto.randomUUID(),userId,title,body,read:false,time:"Just now"},...n]);
 const flash=(s:string)=>{setNotice(s);setTimeout(()=>setNotice(""),2600)};
 const updateTask=(id:string,patch:Partial<Task>)=>{setTasks(ts=>ts.map(t=>t.id===id?{...t,...patch}:t));log(`Updated task ${id}`);flash("Task updated");};
  const selectView=(v:View)=>{setView(v);setTaskId(null);setProjectId(null);setProfileOpen(false);setNotificationsOpen(false);setSearchQuery("");window.scrollTo({top:0,behavior:"smooth"})};
  const openSearchResult=(result:(typeof searchResults)[number])=>{setSearchQuery("");if(result.kind==="task"){setView("Tasks");setProjectId(null);setTaskId(result.target)}else if(result.kind==="project"){setView("Projects");setTaskId(null);setProjectId(result.target)}else selectView(result.target as View)};
  useEffect(()=>{if(!user)return;setLoading(true);const timer=window.setTimeout(()=>setLoading(false),260);return()=>window.clearTimeout(timer)},[user?.id,view,taskId]);
  useEffect(()=>{setTeam(current=>{let changed=false;const next=current.map(person=>{const shouldManage=["u2","u6","u7"].includes(person.id)||String(person.role)==="Department Admin";const accessRole=person.id==="u1"?"Superadmin":shouldManage?"Manager":accessOf(person);const employmentType=employmentOf(person);const accountStatus=accountOf(person);const email=person.id==="u1"?"info@olyxee.com":person.email;const reportsTo=person.id==="u5"?"u7":shouldManage?"u1":person.reportsTo;const role=accessRole==="Manager"?"Manager":accessRole==="Superadmin"||accessRole==="Admin"?"Super Admin":employmentType==="Intern"?"Intern":"Member";const active=accountStatus==="Active";if(!person.accessRole||!person.employmentType||!person.accountStatus||email!==person.email||reportsTo!==person.reportsTo||role!==person.role||active!==person.active){changed=true;return {...person,accessRole,employmentType,accountStatus,email,reportsTo,role,active}}return person});return changed?next:current})},[]);
  if(!user)return <Login onSelect={u=>{setUser(u);setView(accessOf(u)==="Member"?"Tasks":"Overview")}}/>;
  if(loading)return <LoadingShell user={active}/>;
 const selected=visibleTasks.find(t=>t.id===taskId);
  return <div className="app workspace-shell">
     <main className="main"><header className="topbar workspace-topbar"><button className="workspace-brand" onClick={()=>selectView("Overview")}><img src="/olyxee-logo.png" alt="Olyxee"/><b>OLYXEE OPS</b></button><div className="global-search"><Search size={15}/><input value={searchQuery} onChange={event=>setSearchQuery(event.target.value)} placeholder="Search the entire workspace…"/>{searchQuery&&<button onClick={()=>setSearchQuery("")}><X size={14}/></button>}{searchQuery&&<div className="search-results">{searchResults.map(result=><button key={result.id} onClick={()=>openSearchResult(result)}><span><b>{result.label}</b><small>{result.meta}</small></span><ChevronRight size={14}/></button>)}{!searchResults.length&&<div className="search-empty">No matching workspace items.</div>}</div>}</div><div className="top-actions"><span className="week">W38 · 14–18 SEP 2026</span><NotificationPopover notices={activeNotices} open={notificationsOpen} onToggle={()=>{setNotificationsOpen(open=>!open);setProfileOpen(false)}}/><ProfilePopover person={active} status={activeStatus} open={profileOpen} onToggle={()=>{setProfileOpen(open=>!open);setNotificationsOpen(false)}} onSettings={()=>{setProfileOpen(false);setSettingsOpen(true)}} onSwitch={()=>{setProfileOpen(false);setUser(null)}}/></div></header>
        <div className="content workspace-content">{notice&&<div className="notice" style={{marginBottom:17}}>{notice}</div>}{selected?<div className="workspace-section"><TaskDetail task={selected} user={active} can={can} update={updateTask} onBack={()=>setTaskId(null)} onReport={()=>setModal("blocker")}/></div>:projectId?<div className="workspace-section"><ProjectDetail project={projectsData.find(project=>project.id===projectId)!} tasks={tasks} team={team} onBack={()=>setProjectId(null)} onOpen={setTaskId}/></div>:visibleView==="Overview"?<UnifiedWorkspace user={active} team={team} statuses={staffStatuses} tasks={visibleTasks} allTasks={tasks} projectsData={projectsData} objectives={objectives} can={can} onOpen={setTaskId} onProject={setProjectId} onModal={setModal} onManage={person=>{setEditingPerson(person);setModal("person")}} onView={selectView}/>:<div className="workspace-section"><button className="workspace-back" onClick={()=>selectView("Overview")}><ArrowLeft size={15}/> Back to Overview</button><ViewContent view={visibleView} user={active} team={team} statuses={staffStatuses} tasks={visibleTasks} allTasks={tasks} projectsData={projectsData} audit={audit} notices={notices.filter(n=>n.userId===active.id)} objectives={objectives} can={can} onOpen={setTaskId} onProject={setProjectId} onView={selectView} onModal={setModal} onManage={person=>{setEditingPerson(person);setModal("person")}} update={updateTask} setTasks={setTasks} setObjectives={setObjectives} log={log} flash={flash}/></div>}</div></main>
  {modal==="task"&&<TaskModal user={active} team={team} projectNames={projectsData.map(project=>project.name)} onClose={()=>setModal(null)} onSave={t=>{setTasks(x=>[{...t,id:`OLX-${Math.floor(200+Math.random()*80)}`},...x]);log("Created a new task");flash("Task created");setModal(null)}}/>}
    {modal==="person"&&<PersonModal user={active} team={team} person={editingPerson} onClose={()=>{setModal(null);setEditingPerson(undefined)}} onSave={person=>{const role=person.accessRole==="Manager"?"Manager":["Superadmin","Admin"].includes(person.accessRole)?"Super Admin":person.employmentType==="Intern"?"Intern":"Member";const normalized={...person,role,active:person.accountStatus==="Active",reportsTo:["Superadmin","Admin","Manager"].includes(person.accessRole)?"u1":person.reportsTo||"u1"};setTeam(current=>person.id?current.map(existing=>existing.id===person.id?normalized:existing):[...current,{...normalized,id:crypto.randomUUID()}]);log(`${person.id?"Updated":"Added"} ${person.name}`);flash(`${person.name} ${person.id?"updated":"added to team"}`);setModal(null);setEditingPerson(undefined)}}/>}
    {modal==="project"&&<ProjectModal team={team} onClose={()=>setModal(null)} onSave={project=>{setProjectsData(current=>[...current,{...project,id:crypto.randomUUID()}]);log(`Created project ${project.name}`);project.assigneeIds.forEach(id=>notify(id,"Project assigned",`${project.name} is now available in Projects.`));flash("Project created");setModal(null)}}/>}
  {modal==="blocker"&&selected&&<BlockerModal onClose={()=>setModal(null)} onSave={blocker=>{updateTask(selected.id,{status:"Blocked",blocker:{...blocker,reportedBy:active.id,createdAt:"2026-09-16"}});notify("u2","Blocker raised",`${selected.id}: ${blocker.reason}`);setModal(null)}}/>}
  {modal==="objective"&&<ObjectiveModal managers={team.filter(person=>isManager(person)&&accountOf(person)==="Active")} onClose={()=>setModal(null)} onSave={objective=>{setObjectives(current=>[...current,{...objective,id:`WO-${String(current.length+1).padStart(2,"0")}`,createdBy:active.id,createdDate:"2026-09-16",status:"Not started"}]);log(`Created weekly objective ${objective.title}`);flash("Weekly objective created");setModal(null)}}/>}
  {settingsOpen&&<SettingsModal user={active} team={team} setTeam={setTeam} statuses={staffStatuses} setStatuses={setStaffStatuses} tasks={tasks} flash={flash} onClose={()=>setSettingsOpen(false)}/>}
 </div>
}
function Login({onSelect}:{onSelect:(u:User)=>void}){return <div className="login"><div className="login-card"><div className="eyebrow">OLYXEE / INTERNAL</div><h1>Sign in to Ops</h1><p>Choose a demo account to continue. Each access role has a deliberately different operating view.</p>{users.slice(0,3).map(u=><button className="account" key={u.id} onClick={()=>onSelect(u)}><span><b>{u.name}</b><br/><small className="muted">{u.email} · {u.employmentType} · {u.accessRole}</small></span><ChevronRight size={15}/></button>)}<div className="notice" style={{marginTop:22}}>Demo week <b>14–18 September 2026</b>. Changes persist in this browser.</div></div></div>}
function LoadingShell({user}:{user:User}){return <div className="app"><aside className="sidebar"><div className="brand">OLYXEE OPS<span>INTERNAL OPERATING SYSTEM</span></div>{["Overview","Tasks","Projects","People","Blockers","Friday Review"].map(label=><div className="skeleton-nav" key={label}><span className="skeleton skeleton-icon"/><span className="skeleton skeleton-nav-text"/></div>)}</aside><main className="main"><header className="topbar"><span className="skeleton skeleton-crumb"/><span className="skeleton skeleton-avatar"/></header><div className="content"><div className="skeleton skeleton-eyebrow"/><div className="skeleton skeleton-heading"/><div className="skeleton skeleton-subtitle"/><div className="grid stats">{[1,2,3,4].map(item=><div className="panel stat" key={item}><span className="skeleton skeleton-stat-label"/><span className="skeleton skeleton-stat-number"/><span className="skeleton skeleton-stat-note"/></div>)}</div><div className="grid cols"><SkeletonPanel rows={4}/><SkeletonPanel rows={4}/></div><span className="sr-only">Loading {user.name}'s workspace</span></div></main></div>}
function SkeletonPanel({rows}:{rows:number}){return <div className="panel"><div className="panel-head"><span className="skeleton skeleton-panel-title"/></div><div className="list">{Array.from({length:rows},(_,index)=><div className="row" key={index}><div className="row-main"><span className="skeleton skeleton-row-title"/><span className="skeleton skeleton-row-meta"/></div><span className="skeleton skeleton-badge"/></div>)}</div></div>}
function Header({eyebrow,title,subtitle,action}:{eyebrow:string;title:string;subtitle?:string;action?:React.ReactNode}){return <div className="page-head"><div><div className="eyebrow">{eyebrow}</div><h1 className="title">{title}</h1>{subtitle&&<p className="subtitle">{subtitle}</p>}</div>{action}</div>}
function Status({s}:{s:string}){let c=["Done","Approved","Complete"].includes(s)?"green":["Blocked","Rejected","At risk"].includes(s)?"red":["In Review","Pending","In progress"].includes(s)?"amber":"gray";return <span className={`badge ${c}`}>{s}</span>}
function StatusPill({status}:{status?:StaffStatus}){const value=status?.availability||"Offline";return <span className={`availability ${value.toLowerCase()}`}><i/>{value}</span>}
function NotificationPopover({notices,open,onToggle}:{notices:Notice[];open:boolean;onToggle:()=>void}){return <div className="notification-wrap"><button className="close notification-trigger" title="Notifications" aria-expanded={open} aria-haspopup="dialog" onClick={onToggle}><Bell size={17}/>{notices.some(item=>!item.read)&&<i/>}</button>{open&&<div className="notification-popover" role="dialog" aria-label="Notifications"><div className="notification-head"><div><b>Notifications</b><span>{notices.length} updates</span></div><button className="close" onClick={onToggle}><X size={16}/></button></div><div className="notification-list">{notices.slice(0,5).map(item=><div className="notification-item" key={item.id}><div className={`notification-mark ${item.read?"read":""}`}/><div><b>{item.title}</b><p>{item.body}</p><span>{item.time}</span></div></div>)}{!notices.length&&<div className="empty"><strong>All clear</strong>No notifications need your attention.</div>}</div></div>}</div>}
function ProfilePopover({person,status,open,onToggle,onSettings,onSwitch}:{person:User;status?:StaffStatus;open:boolean;onToggle:()=>void;onSettings:()=>void;onSwitch:()=>void}){const availability=status?.availability||"Offline";return <div className="profile-wrap"><button className="top-profile" aria-expanded={open} aria-haspopup="menu" onClick={onToggle}><Avatar person={person}/><span className="profile-copy"><b>{person.name}</b><small>{accessOf(person)} · {availability}</small></span><ChevronRight className={`profile-chevron ${open?"open":""}`} size={14}/></button>{open&&<div className="profile-menu profile-menu-rich profile-menu-ios" role="menu"><div className="profile-ios-account"><Avatar person={person} size={62}/><b>{person.name}</b><span>{person.email}</span><small><i className={`availability-dot ${availability.toLowerCase()}`}/>{availability} · {person.department}</small></div><div className="profile-ios-actions"><button role="menuitem" onClick={onSettings}><span className="profile-action-icon"><Settings size={18}/></span><b>Settings</b><ChevronRight size={15}/></button><button role="menuitem" onClick={onSwitch}><span className="profile-action-icon neutral"><LogOut size={18}/></span><b>Switch account</b><ChevronRight size={15}/></button></div></div>}</div>}
function UnifiedWorkspace({user,team,statuses,tasks,allTasks,projectsData,objectives,can,onOpen,onProject,onModal,onManage,onView}:{user:User;team:User[];statuses:StaffStatus[];tasks:Task[];allTasks:Task[];projectsData:Project[];objectives:WeeklyObjective[];can:(x:string)=>boolean;onOpen:(id:string)=>void;onProject:(id:string)=>void;onModal:(x:"task"|"person"|"blocker"|"project"|"objective"|null)=>void;onManage:(user:User)=>void;onView:(view:View)=>void}){
  const blocked=tasks.filter(task=>task.status==="Blocked"); const review=tasks.filter(task=>task.status==="In Review");
  const scopedProjects=projectsData.filter(project=>isAdmin(user)||project.assigneeIds.includes(user.id));
  const scopedPeople=team.filter(person=>isAdmin(user)||person.id===user.id||person.reportsTo===user.id);
  const scopedObjectives=objectives.filter(objective=>isAdmin(user)||objective.managerId===user.id);
  const visibleDepartments=departments.filter(department=>isAdmin(user)||department[0]===user.department);
  return <div className={`workspace-board ${accessOf(user)==="Member"?"workspace-board-member":""}`}>
    <div className="workspace-stack workspace-stack-summary">
    <section id="workspace-overview" className="workspace-card workspace-welcome"><Avatar person={user} size={92}/><div className="workspace-profile-copy"><h1>{user.name}</h1><p>{user.email}</p><b>{accessOf(user)}</b><small>{employmentOf(user)} · {user.department}</small></div><span className="workspace-week">Week 38 · 14–18 Sep 2026</span></section>
    </div>
    <div className="workspace-stack workspace-stack-work">
    <section id="workspace-tasks" className="workspace-card workspace-tasks"><div className="workspace-card-head"><div><span className="workspace-icon blue"><ClipboardList size={17}/></span><b>Tasks</b></div><span className="workspace-head-actions">{can("task")&&<button onClick={()=>onModal("task")}><Plus size={14}/> New</button>}<button onClick={()=>onView("Tasks")}>Open <ChevronRight size={13}/></button></span></div><div className="workspace-list">{tasks.filter(task=>!["Done","Cancelled"].includes(task.status)).slice(0,6).map(task=><button key={task.id} onClick={()=>onOpen(task.id)}><span><b>{task.title}</b><small>{task.id} · {task.project} · Due {task.due}</small></span><Status s={task.status}/></button>)}{!tasks.length&&<div className="workspace-empty">No tasks in your workspace.</div>}</div></section>
    <section id="workspace-projects" className="workspace-card workspace-projects"><div className="workspace-card-head"><div><span className="workspace-icon amber"><BriefcaseBusiness size={17}/></span><b>Projects</b></div><span className="workspace-head-actions">{isAdmin(user)&&<button onClick={()=>onModal("project")}><Plus size={14}/> New</button>}<button onClick={()=>onView("Projects")}>Open <ChevronRight size={13}/></button></span></div><div className="workspace-project-grid">{scopedProjects.slice(0,4).map(project=>{const people=project.assigneeIds.map(id=>team.find(person=>person.id===id)).filter(Boolean) as User[];return <button key={project.id} onClick={()=>onProject(project.id)}><ProjectLogo project={project} size={38}/><span><b>{project.name}</b><small>{project.description}</small></span><AvatarStack people={people}/></button>})}{!scopedProjects.length&&<div className="workspace-empty">No assigned projects.</div>}</div></section>
    </div>
    {accessOf(user)!=="Member"&&<div className="workspace-stack workspace-stack-operations">
    <section id="workspace-people" className="workspace-card workspace-people"><div className="workspace-card-head"><div><span className="workspace-icon violet"><Users size={17}/></span><b>{isManager(user)?"Staff":"People"}</b></div><span className="workspace-head-actions">{can("person")&&<button onClick={()=>onModal("person")}><UserPlus size={14}/> Add</button>}<button onClick={()=>onView("People")}>Open <ChevronRight size={13}/></button></span></div><div className="workspace-list">{scopedPeople.filter(person=>person.id!==user.id).slice(0,5).map(person=>{const status=statuses.find(item=>item.userId===person.id);return <button key={person.id} onClick={()=>onManage(person)}><span className="workspace-person-row"><Avatar person={person} size={32}/><span><b>{person.name}</b><small>{employmentOf(person)} · {accessOf(person)}</small></span></span><StatusPill status={status}/></button>})}{scopedPeople.filter(person=>person.id!==user.id).length===0&&<div className="workspace-empty">No staff assigned.</div>}</div></section>
    <section id="workspace-departments" className="workspace-card workspace-departments"><div className="workspace-card-head"><div><span className="workspace-icon teal"><Building2 size={17}/></span><b>Departments</b></div><button onClick={()=>onView("Departments")}>Open <ChevronRight size={13}/></button></div><div className="workspace-department-grid">{visibleDepartments.map(department=>{const departmentTasks=allTasks.filter(task=>task.department===department[0]);const done=departmentTasks.filter(task=>task.status==="Done").length;return <div key={department[0]}><span><b>{department[0]}</b><small>{department[1]}</small></span><strong>{done}/{departmentTasks.length}</strong></div>})}</div></section>
    <section id="workspace-review" className="workspace-card workspace-review"><div className="workspace-card-head"><div><span className="workspace-icon green"><FileCheck2 size={17}/></span><b>Weekly review</b></div><span className="workspace-head-actions">{isAdmin(user)&&<button onClick={()=>onModal("objective")}><Plus size={14}/> Objective</button>}<button onClick={()=>onView("Weekly Review")}>Open <ChevronRight size={13}/></button></span></div><div className="workspace-objectives">{scopedObjectives.slice(0,4).map(objective=><div key={objective.id}><span><b>{objective.title}</b><small>{objective.priority} priority · Due {objective.dueDate}</small></span><Status s={objective.status}/></div>)}{!scopedObjectives.length&&<div className="workspace-empty">No weekly objectives assigned.</div>}</div>{(review.length>0||blocked.length>0)&&<button className="workspace-review-link" onClick={()=>onView("Weekly Review")}>Review {review.length+blocked.length} decisions <ChevronRight size={14}/></button>}</section>
    </div>}
  </div>
}
function ViewContent(p:{view:View;user:User;team?:User[];statuses:StaffStatus[];tasks:Task[];allTasks:Task[];projectsData:Project[];audit:Audit[];notices?:Notice[];objectives:WeeklyObjective[];can:(x:string)=>boolean;onOpen:(id:string)=>void;onProject:(id:string)=>void;onView:(v:View)=>void;onModal:(x:"task"|"person"|"blocker"|"project"|"objective"|null)=>void;onManage:(u:User)=>void;update:(id:string,x:Partial<Task>)=>void;setTasks:React.Dispatch<React.SetStateAction<Task[]>>;setObjectives:React.Dispatch<React.SetStateAction<WeeklyObjective[]>>;log:(s:string)=>void;flash:(s:string)=>void}){
    const {view,user,tasks,audit}=p; const mine=tasks.filter(t=>t.assignee===user.id); const [peopleFilter,setPeopleFilter]=useState<"All"|"Employee"|"Intern">("All"); const [selectedDepartment,setSelectedDepartment]=useState<string|null>(null);
  if(view==="Overview"){
    const commitments=tasks.filter(t=>t.weeklyCommitment);
    const delivered=commitments.filter(t=>t.status==="Done");
    const review=commitments.filter(t=>t.status==="In Review");
    const blocked=commitments.filter(t=>t.status==="Blocked");
    const active=commitments.filter(t=>!["Done","Cancelled"].includes(t.status));
    const completion=commitments.length?Math.round(delivered.length/commitments.length*100):0;
     const overdue=active.filter(t=>t.due<="2026-09-18"&&!blocked.includes(t)&&!review.includes(t));
     const attention=(user.role==="Super Admin"?[...blocked,...review,...overdue]:[...blocked,...review,...active.filter(t=>!blocked.includes(t)&&!review.includes(t))])
      .sort((a,b)=>a.due.localeCompare(b.due)).slice(0,5);
    const owner=(id?:string)=>id?((p.team||users).find(u=>u.id===id)?.name||"Unassigned"):"Unassigned";
     const myObjectives=p.objectives.filter(o=>user.role==="Super Admin"||o.managerId===user.id);
      if(user.role==="Manager"){
        const directReports=(p.team||[]).filter(person=>person.reportsTo===user.id&&person.active!==false);
        const decisions=[...blocked,...review].sort((a,b)=>a.due.localeCompare(b.due)).slice(0,4);
        const completeObjectives=myObjectives.filter(objective=>objective.status==="Complete").length;
        return <div className="manager-overview"><Header eyebrow="Manager overview / Week 38" title={`Good morning, ${user.name.split(" ")[0]}.`} subtitle="Your priorities, team delivery, and decisions that need attention."/>
          <div className="grid stats manager-overview-stats">
            <div className="panel stat"><div className="stat-label">Your objectives</div><div className="stat-num">{completeObjectives}<span className="stat-denom"> / {myObjectives.length}</span></div><div className="stat-note">completed this week</div></div>
            <div className="panel stat"><div className="stat-label">Team delivery</div><div className="stat-num">{delivered.length}<span className="stat-denom"> / {commitments.length}</span></div><div className="stat-note">weekly commitments delivered</div></div>
            <div className="panel stat"><div className="stat-label">Needs a decision</div><div className="stat-num">{decisions.length}</div><div className="stat-note">{decisions.length?"blocked or awaiting review":"nothing waiting"}</div></div>
          </div>
          {myObjectives.length>0&&<div className="panel manager-priority"><div className="panel-head"><span className="panel-title">Your weekly objective</span><button className="panel-link" onClick={()=>p.onView("Weekly Review")}>Open Weekly Review <ChevronRight size={13}/></button></div><div className="list">{myObjectives.map(objective=><div className="row" key={objective.id}><div className="row-main"><div className="row-title">{objective.title}</div><div className="row-meta">{objective.priority} priority · Due {objective.dueDate}</div></div><Status s={objective.status}/></div>)}</div></div>}
          <div className="grid cols manager-overview-columns">
            <div className="panel"><div className="panel-head"><span className="panel-title">Needs your decision</span><span className="mono">{decisions.length} items</span></div><div className="list">{decisions.map(task=><button className="row overview-row" key={task.id} onClick={()=>p.onOpen(task.id)}><div className="row-main"><div className="row-title">{task.title}</div><div className="row-meta">{owner(task.assignee)} · {task.project} · Due {task.due}</div></div><Status s={task.status}/><ChevronRight size={14}/></button>)}{!decisions.length&&<div className="empty"><strong>Nothing waiting</strong>No blockers or reviews need your decision.</div>}</div></div>
            <div className="panel"><div className="panel-head"><span className="panel-title">Staff today</span><button className="panel-link" onClick={()=>p.onView("People")}>Open Staff <ChevronRight size={13}/></button></div><div className="list">{directReports.map(person=>{const status=p.statuses.find(item=>item.userId===person.id);const activeWork=p.allTasks.filter(task=>task.assignee===person.id&&!["Done","Cancelled"].includes(task.status)).length;return <div className="row" key={person.id}><div className="inline"><Avatar person={person}/><div><div className="row-title">{person.name}</div><div className="row-meta">{activeWork} active {activeWork===1?"task":"tasks"} · {status?.start||"—"}–{status?.end||"—"}</div></div></div><StatusPill status={status}/></div>})}{!directReports.length&&<div className="empty"><strong>No staff assigned</strong>Your direct reports will appear here.</div>}</div></div>
          </div>
        </div>;
      }
    return <><Header eyebrow={user.role==="Super Admin"?"Executive summary / Week 38":"Week 38 / Operating pulse"} title={user.role==="Super Admin"?"Operating summary":`Good morning, ${user.name.split(" ")[0]}.`} subtitle={user.role==="Super Admin"?"Manager priorities, delivery health, and exceptions requiring an executive decision.":"A clear read on commitments, delivery, and where attention is needed."}/>
      <div className="grid stats overview-stats">
        <div className="panel stat"><div className="stat-label">Weekly commitments</div><div className="stat-num">{commitments.length}</div><div className="stat-note">14–18 September · scoped to you</div></div>
        <div className="panel stat"><div className="stat-label">Delivered</div><div className="stat-num">{delivered.length}<span className="stat-denom"> / {commitments.length}</span></div><div className="stat-note">approved with evidence</div></div>
        <div className="panel stat"><div className="stat-label">Review decisions</div><div className="stat-num">{review.length}</div><div className="stat-note">waiting for a decision</div></div>
        <div className="panel stat"><div className="stat-label">Blocked</div><div className="stat-num">{blocked.length}</div><div className="stat-note">{blocked.length?"requires a decision":"no active blockers"}</div></div>
      </div>
        {myObjectives.length>0&&<div className="panel objective-priority"><div className="panel-head"><span className="panel-title">Weekly priorities</span><span className="mono">{myObjectives.length} objectives</span></div><div className="list">{myObjectives.map(o=><div className="row" key={o.id}><div className="row-main"><div className="row-title">{o.title}</div><div className="row-meta">{user.role==="Super Admin"?owner(o.managerId):"Assigned to you"} · Due {o.dueDate}</div></div><Status s={o.status}/></div>)}</div></div>}
       <div className="overview-progress panel"><div><div className="panel-title">Current delivery</div><div className="row-meta">{delivered.length} of {commitments.length} weekly commitments delivered</div></div><strong>{completion}%</strong><div className="delivery-track"><span style={{width:`${completion}%`}}/></div><button className="panel-link" onClick={()=>p.onView("Weekly Review")}>Open Weekly Review <ChevronRight size={13}/></button></div>
       <div className="grid cols overview-columns">
        <div className="panel"><div className="panel-head"><span className="panel-title">{user.role==="Super Admin"?"Executive attention":"Next attention"}</span><span className="mono">{attention.length} items</span></div><div className="list">{attention.map(t=><button className="row overview-row" key={t.id} onClick={()=>p.onOpen(t.id)}><div className="row-main"><div className="row-title">{t.title}</div><div className="row-meta">{t.project} · {owner(t.assignee)} · Due {t.due}</div></div><Status s={t.status}/><ChevronRight size={14}/></button>)}{!attention.length&&<div className="empty">No commitments need executive attention.</div>}</div></div>
        <div className="panel"><div className="panel-head"><span className="panel-title">Decision queue</span><span className="badge amber">{review.length} awaiting</span></div><div className="list">{review.slice(0,4).map(t=><button className="row overview-row" key={t.id} onClick={()=>p.onOpen(t.id)}><div className="row-main"><div className="row-title">{t.title}</div><div className="row-meta">{t.id} · {owner(t.assignee)} · {t.pr?"Evidence linked":"Evidence missing"}</div></div><ChevronRight size={14}/></button>)}{!review.length&&<div className="empty">No review decisions waiting.</div>}<button className="overview-link" onClick={()=>p.onView("Weekly Review")}>View all review decisions <ChevronRight size={13}/></button></div></div>
      </div>
    </>;
  }
   if(view==="Tasks"&&accessOf(user)==="Member"){const available=tasks.filter(t=>(t.available||t.status==="Available")&&!t.assignee);return <><Header eyebrow="Personal queue" title="Tasks" subtitle="Your assigned work and available tasks, ordered by what needs attention."/><div className="grid">{[["DUE NOW",mine.filter(t=>!["Done","Blocked","In Review","Cancelled"].includes(t.status)&&t.due<="2026-09-16")],["NEXT",mine.filter(t=>!["Done","Blocked","In Review","Cancelled"].includes(t.status)&&t.due>"2026-09-16")],["BLOCKED",mine.filter(t=>t.status==="Blocked")],["IN REVIEW",mine.filter(t=>t.status==="In Review")],["AVAILABLE",available],["COMPLETED",mine.filter(t=>t.status==="Done")]].map(([label,items]:any)=><div className="panel" key={label}><div className="panel-head"><span className="panel-title">{label}</span><span className="mono">{items.length}</span></div><div className="list">{items.map((t:Task)=><button className="row" style={{border:0,background:"transparent",width:"100%",textAlign:"left"}} key={t.id} onClick={()=>p.onOpen(t.id)}><div className="row-main"><div className="row-title">{t.title}</div><div className="row-meta">{t.id} · Due {t.due} · {t.project}</div></div><Status s={t.status}/><ChevronRight size={14}/></button>)}{!items.length&&<div className="empty">Nothing here.</div>}</div></div>)}</div></>;}
   if(view==="Tasks")return <><Header eyebrow="Work registry" title="Tasks" subtitle={isAdmin(user)?"The complete delivery record across Olyxee.":`Work for ${user.department}.`} action={p.can("task")&&<button className="btn primary" onClick={()=>p.onModal("task")}><Plus size={14}/> New task</button>}/><TaskList tasks={tasks} {...p}/></>;
    if(view==="Projects"){const assigned=p.projectsData.filter(project=>isAdmin(user)||project.assigneeIds.includes(user.id));return <><Header eyebrow="Delivery map" title="Projects" subtitle={isAdmin(user)?"All active project workspaces and ownership.":"Projects assigned to you and your delivery team."} action={isAdmin(user)&&<button className="btn primary" onClick={()=>p.onModal("project")}><Plus size={14}/> Create project</button>}/><div className="project-intro"><span><b>{assigned.length}</b> active workspaces</span><span>Open a project for delivery context, people, and resources.</span></div><div className="grid project-grid">{assigned.map((project,i)=>{const people=project.assigneeIds.map(id=>(p.team||users).find(person=>person.id===id)).filter(Boolean) as User[];return <button className="panel project-card" key={project.id} onClick={()=>p.onProject(project.id)}><div className="project-card-top"><div className="inline"><ProjectLogo project={project}/><div className="eyebrow">{String(i+1).padStart(2,"0")} / workspace</div></div><Status s={project.status}/></div><div className="task-title">{project.name}</div><p className="project-description">{project.description}</p><div className="project-card-people"><AvatarStack people={people}/><span>{people.length} assigned {people.length===1?"person":"people"}</span></div><div className="project-card-foot"><span>View project</span><ChevronRight size={15}/></div></button>})}{!assigned.length&&<div className="empty">No projects have been assigned to you yet.</div>}</div></>;}
     if(view==="People"){
      const directory=(p.team||users).filter(person=>isAdmin(user)||person.reportsTo===user.id);
      const employees=directory.filter(person=>employmentOf(person)==="Employee"); const interns=directory.filter(person=>employmentOf(person)==="Intern");
      const people=directory.filter(person=>isManager(user)||peopleFilter==="All"||employmentOf(person)===peopleFilter);
      return <><Header eyebrow={isManager(user)?"Direct reports":"Team directory"} title={isManager(user)?"Staff":"People"} subtitle={isManager(user)?"Everyone you are directly responsible for, with availability and contribution visible in one place.":"Employment, access, and account standing in one directory."} action={p.can("person")&&<button className="btn primary" onClick={()=>p.onModal("person")}><UserPlus size={14}/> Add {isManager(user)?"staff member":"person"}</button>}/>
      {isAdmin(user)?<><div className="people-summary"><button className={peopleFilter==="All"?"active":""} onClick={()=>setPeopleFilter("All")}><span>Everyone</span><strong>{directory.length}</strong></button><button className={peopleFilter==="Employee"?"active":""} onClick={()=>setPeopleFilter("Employee")}><span>Employees</span><strong>{employees.length}</strong></button><button className={peopleFilter==="Intern"?"active":""} onClick={()=>setPeopleFilter("Intern")}><span>Interns</span><strong>{interns.length}</strong></button></div><div className="people-filter-note">Showing <b>{peopleFilter==="All"?"everyone":`${peopleFilter.toLowerCase()}s`}</b> · {people.length} people</div></>:<div className="people-summary staff-summary"><button className="active"><span>Your staff</span><strong>{directory.length}</strong></button></div>}
      <div className="panel table-wrap"><table className="table people-table"><thead><tr><th>Person</th><th>Employment</th><th>Access role</th><th>Department</th><th>Reports to</th><th>Availability</th><th>Account</th><th></th></tr></thead><tbody>{people.map(person=>{const staff=p.statuses.find(status=>status.userId===person.id);return <tr key={person.id}><td><div className="inline"><Avatar person={person}/><span><b>{person.name}</b><br/><span className="muted">{person.email}</span></span></div></td><td>{employmentOf(person)}</td><td><span className={`role-pill ${accessOf(person).toLowerCase()}`}>{accessOf(person)}</span></td><td>{person.department}</td><td>{(p.team||users).find(item=>item.id===person.reportsTo)?.name||"—"}</td><td><StatusPill status={staff}/></td><td><span className={`people-status ${accountOf(person).toLowerCase()}`}>{accountOf(person)}</span></td><td>{p.can("person")&&<button className="btn" onClick={()=>p.onManage(person)}>Manage</button>}</td></tr>})}</tbody></table>{!people.length&&<div className="empty"><strong>{isManager(user)?"No staff assigned":"No people found"}</strong>{isManager(user)?"Add a staff member or ask an administrator to update reporting lines.":"Try another employment filter."}</div>}</div></>;
     }
   if(view==="Departments"){
     const directory=p.team||users;
      const visibleDepartments=departments.filter(d=>isAdmin(user)||d[0]===user.department);
     const owner=(id?:string)=>id?directory.find(person=>person.id===id)?.name||"Unassigned":"Unassigned";
     const departmentTasks=(name:string)=>p.allTasks.filter(task=>task.department===name);
     const departmentPeople=(name:string)=>directory.filter(person=>person.department===name);
     if(selectedDepartment){
       const department=visibleDepartments.find(d=>d[0]===selectedDepartment);
       if(!department)return null;
       const departmentTaskList=departmentTasks(selectedDepartment);
        const weeklyTasks=departmentTaskList.filter(task=>task.weeklyCommitment);
        const delivered=weeklyTasks.filter(task=>task.status==="Done").length;
        const inReview=weeklyTasks.filter(task=>task.status==="In Review").length;
        const blocked=weeklyTasks.filter(task=>task.status==="Blocked").length;
        const completion=weeklyTasks.length?Math.round(delivered/weeklyTasks.length*100):0;
         const managerIds=directory.filter(person=>person.department===selectedDepartment&&isManager(person)).map(person=>person.id);
         const departmentObjectives=p.objectives.filter(objective=>isManager(user)?objective.managerId===user.id:managerIds.includes(objective.managerId));
         const contributionPeople=isManager(user)?directory.filter(person=>person.reportsTo===user.id):departmentPeople(selectedDepartment);
       return <div className="department-detail">
         <button className="btn department-back" onClick={()=>setSelectedDepartment(null)}><ArrowLeft size={14}/> All departments</button>
          <Header eyebrow="Department workspace" title={selectedDepartment} subtitle={`${department[1]} · Weekly objectives, delivery performance, and team contribution.`}/>
         <div className="department-overview">
            <div><span className="stat-label">Weekly delivery</span><strong>{completion}%</strong><div className="department-progress"><span style={{width:`${completion}%`}}/></div></div>
            <div><span className="stat-label">Delivered</span><strong>{delivered} / {weeklyTasks.length}</strong><span className="row-meta">weekly commitments complete</span></div>
            <div><span className="stat-label">In review</span><strong>{inReview}</strong><span className="row-meta">{inReview?"waiting for a decision":"nothing waiting"}</span></div>
           <div><span className="stat-label">Blockers</span><strong className={blocked?"metric-alert":""}>{blocked}</strong><span className="row-meta">{blocked?"needs attention":"clear for now"}</span></div>
         </div>
          <div className="grid cols department-insights">
             <div className="panel"><div className="panel-head"><span className="panel-title">Weekly objectives</span><span className="mono">{departmentObjectives.length} priorities</span></div><div className="list">{departmentObjectives.map(objective=><div className="row" key={objective.id}><div className="row-main"><div className="row-title">{objective.title}</div><div className="row-meta">{isAdmin(user)?owner(objective.managerId):"Assigned to you"} · {objective.priority} priority · Due {objective.dueDate}</div></div><Status s={objective.status}/></div>)}{!departmentObjectives.length&&<div className="empty"><strong>No weekly objectives</strong>No manager objective is assigned to this department.</div>}</div></div>
             <div className="panel"><div className="panel-head"><span className="panel-title">{isManager(user)?"Staff contribution":"Team contribution"}</span><span className="mono">{contributionPeople.length} people</span></div><div className="list">{contributionPeople.map(person=>{const status=p.statuses.find(item=>item.userId===person.id);const done=p.allTasks.filter(task=>task.assignee===person.id&&task.status==="Done").length;return <div className="row" key={person.id}><div className="inline"><Avatar person={person}/><div><div className="row-title">{person.name}</div><div className="row-meta">{done} completed tasks · {status?.start||"—"}–{status?.end||"—"}</div></div></div><StatusPill status={status}/></div>})}{!contributionPeople.length&&<div className="empty"><strong>No staff assigned</strong>There are no contribution records for this department.</div>}</div></div>
          </div>
         <div className="panel department-work">
           <div className="panel-head"><span className="panel-title">Department tasks</span><span className="mono">{departmentTaskList.length} total</span></div>
           <div className="list">{departmentTaskList.map(task=><button className="row department-task-row" key={task.id} onClick={()=>p.onOpen(task.id)}>
             <div className="row-main"><div className="row-title">{task.title}</div><div className="row-meta">{task.id} · {owner(task.assignee)} · Due {task.due}</div></div><Status s={task.status}/><ChevronRight size={14}/>
           </button>)}{!departmentTaskList.length&&<div className="empty"><strong>No department tasks</strong>There is no delivery work recorded for this department.</div>}</div>
         </div>
       </div>;
     }
      return <><Header eyebrow="Organization" title="Departments" subtitle={isAdmin(user)?"A concise operating view across every department.":"Your department's delivery health and current work."}/><div className="department-grid">{visibleDepartments.map(d=>{
       const departmentTaskList=departmentTasks(d[0]); const people=departmentPeople(d[0]); const completed=departmentTaskList.filter(task=>task.status==="Done").length; const open=departmentTaskList.filter(task=>!["Done","Cancelled"].includes(task.status)).length; const blocked=departmentTaskList.filter(task=>task.status==="Blocked").length; const completion=departmentTaskList.length?Math.round(completed/departmentTaskList.length*100):0;
       return <button className="panel department-card" key={d[0]} onClick={()=>setSelectedDepartment(d[0])}><div className="department-card-head"><div><div className="eyebrow">Department</div><div className="task-title">{d[0]}</div></div><ChevronRight size={16}/></div><div className="row-meta">Lead · {d[1]}</div><div className="department-meter"><span style={{width:`${completion}%`}}/></div><div className="department-card-stats"><span><b>{completion}%</b> complete</span><span><b>{open}</b> open</span><span className={blocked?"metric-alert":""}><b>{blocked}</b> blocked</span><span><b>{people.length}</b> people</span></div></button>;
     })}</div></>;
   }
  if(view==="Blockers")return <><Header eyebrow="Needs a decision" title="Blockers" subtitle="Surface constraints early. Resolve or replan with context."/><div className="panel table-wrap"><table className="table"><thead><tr><th>Task</th><th>Blocker</th><th>Owner</th><th>Action</th></tr></thead><tbody>{tasks.filter(t=>t.status==="Blocked").map(t=><tr key={t.id}><td><b>{t.title}</b><br/><span className="muted">{t.id}</span></td><td>{t.blocker?.reason}</td><td>{users.find(u=>u.id===t.assignee)?.name}</td><td><button className="btn" onClick={()=>p.onOpen(t.id)}>Open task</button></td></tr>)}</tbody></table></div></>;
    if(view==="Weekly Review")return <Review tasks={tasks} objectives={p.objectives} team={p.team||users} user={user} onOpen={p.onOpen} onNewObjective={()=>p.onModal("objective")} update={p.update} setObjectives={p.setObjectives} can={p.can} flash={p.flash}/>;
 if(view==="Notifications")return <><Header eyebrow="Updates" title="Notifications" subtitle="The decisions and changes that need your attention."/><div className="panel"><div className="list">{(p.notices||[]).map(n=><div className="row" key={n.id}><div className="inline"><div className="avatar" style={{background:n.title.includes("blocked")?"#f4e4e1":"#e6efe9"}}>O</div><div><div className="row-title">{n.title}</div><div className="row-meta">{n.body} · {n.time}</div></div></div><ChevronRight size={15}/></div>)}{!(p.notices||[]).length&&<div className="empty">No notifications.</div>}</div></div></>;
 if(view==="Integrations")return <><Header eyebrow="Connection architecture" title="Integrations" subtitle="Demo connection architecture; no live external services are connected."/><div className="notice" style={{marginBottom:16}}>GitHub PR links are accepted as evidence today. A webhook-ready adapter can sync merge events later without changing the review model.</div><div className="panel"><div className="list">{[["GitHub","PR evidence and webhook-ready merge events","Demo architecture","amber"],["Linear","Commitment import adapter","Planned","gray"],["Slack","Blocker notifications","Not connected","gray"]].map(x=><div className="row" key={x[0]}><div className="inline"><div className="avatar">{x[0][0]}</div><div><div className="row-title">{x[0]}</div><div className="row-meta">{x[1]}</div></div></div><span className={`badge ${x[3]}`}>{x[2]}</span></div>)}</div></div></>;
 if(view==="Audit Log")return <><Header eyebrow="Traceability" title="Audit Log" subtitle="Every important change has an actor and a timestamp."/><div className="panel table-wrap"><table className="table"><thead><tr><th>Event</th><th>Actor</th><th>When</th></tr></thead><tbody>{(audit.length?audit:[{id:"1",action:"Seeded demo workspace",actor:"System",time:"Today"} as Audit]).map(a=><tr key={a.id}><td>{a.action}</td><td>{a.actor}</td><td className="mono">{a.time}</td></tr>)}</tbody></table></div></>;
  return <SettingsView tasks={tasks} setTasks={p.setTasks} flash={p.flash} />;
}
function TaskList({tasks,onOpen,update,user,can,flash}:any){const [q,setQ]=useState("");const [status,setStatus]=useState("All");const filtered=tasks.filter((t:Task)=>(status==="All"||t.status===status)&&`${t.title} ${t.project} ${t.id}`.toLowerCase().includes(q.toLowerCase()));return <><div className="filters"><div className="input search inline"><Search size={14}/><input style={{border:0,outline:0,width:"100%"}} placeholder="Search tasks" value={q} onChange={e=>setQ(e.target.value)}/></div><select className="select" value={status} onChange={e=>setStatus(e.target.value)}><option value="All">All statuses</option>{["Inbox","Planned","Available","Assigned","In Progress","Blocked","In Review","Done","Cancelled"].map(s=><option key={s}>{s}</option>)}</select></div><div className="panel table-wrap"><table className="table"><thead><tr><th>Task</th><th>Project</th><th>Owner</th><th>Due</th><th>Status</th><th></th></tr></thead><tbody>{filtered.map((t:Task)=><tr key={t.id}><td><b>{t.title}</b><br/><span className="muted">{t.id} · {t.priority} priority</span></td><td>{t.project}</td><td>{t.assignee?users.find(u=>u.id===t.assignee)?.name:"Unassigned"}</td><td>{t.due}</td><td><Status s={t.status}/></td><td><button className="btn" onClick={()=>onOpen(t.id)}>Open</button>{(t.available||t.status==="Available")&&!t.assignee&&<button className="btn" style={{marginLeft:5}} onClick={()=>{update(t.id,{assignee:user.id,status:"Assigned",available:false});flash("Task claimed")}}>Claim</button>}</td></tr>)}</tbody></table>{!filtered.length&&<div className="empty"><strong>No matching tasks</strong>Try a different search.</div>}</div></>}

function Github({size=15}:{size?:number}){return <svg aria-hidden="true" width={size} height={size} viewBox="0 0 24 24" fill="currentColor"><path d="M12 .7a12 12 0 0 0-3.79 23.39c.6.11.82-.26.82-.58v-2.24c-3.34.73-4.04-1.61-4.04-1.61-.55-1.39-1.34-1.76-1.34-1.76-1.09-.75.08-.74.08-.74 1.2.09 1.83 1.23 1.83 1.23 1.07 1.83 2.8 1.3 3.49.99.11-.77.42-1.3.76-1.6-2.67-.3-5.47-1.34-5.47-5.96 0-1.32.47-2.4 1.23-3.25-.12-.3-.53-1.53.12-3.2 0 0 1-.33 3.3 1.24a11.5 11.5 0 0 1 6 0c2.29-1.57 3.3-1.24 3.3-1.24.65 1.67.24 2.9.12 3.2.77.85 1.23 1.93 1.23 3.25 0 4.63-2.8 5.65-5.48 5.95.43.37.81 1.1.81 2.22v3.29c0 .32.22.7.83.58A12 12 0 0 0 12 .7Z"/></svg>}
function ProjectDetail({project,tasks,team,onBack,onOpen}:{project:Project;tasks:Task[];team:User[];onBack:()=>void;onOpen:(id:string)=>void}){
 const projectTasks=tasks.filter(task=>task.project===project.name); const done=projectTasks.filter(task=>task.status==="Done").length; const open=projectTasks.filter(task=>!["Done","Cancelled"].includes(task.status)).length; const completion=projectTasks.length?Math.round(done/projectTasks.length*100):0;
 return <div className="project-detail"><button className="btn" onClick={onBack}><ArrowLeft size={14}/> Back to projects</button><div className="project-detail-head"><div className="project-heading"><ProjectLogo project={project} size={58}/><div><div className="eyebrow">Project workspace / {project.id}</div><h1 className="title">{project.name}</h1><p className="subtitle">{project.description}</p></div></div><a className="btn github-button" href={project.githubUrl} target="_blank" rel="noreferrer"><Github size={15}/> Open GitHub</a></div><div className="project-overview"><div><span className="stat-label">Delivery status</span><Status s={project.status}/></div><div><span className="stat-label">Completion</span><strong>{completion}%</strong><div className="project-progress"><span style={{width:`${completion}%`}}/></div></div><div><span className="stat-label">Open work</span><strong>{open} tasks</strong></div><div><span className="stat-label">Owners</span><strong>{project.assigneeIds.length} people</strong></div></div><div className="project-detail-grid"><section className="panel"><div className="panel-head"><span className="panel-title">Delivery work</span><span className="mono">{projectTasks.length} tasks</span></div><div className="list">{projectTasks.map(task=><button className="row project-task-row" key={task.id} onClick={()=>onOpen(task.id)}><div className="row-main"><div className="row-title">{task.title}</div><div className="row-meta">{task.id} · Due {task.due} · {task.assignee?team.find(person=>person.id===task.assignee)?.name:"Unassigned"}</div></div><Status s={task.status}/><ChevronRight size={14}/></button>)}{!projectTasks.length&&<div className="empty">No tasks have been added to this project.</div>}</div></section><aside className="project-side"><section className="panel detail-section"><h3>Assigned people</h3>{project.assigneeIds.map(id=>{const person=team.find(item=>item.id===id);return <div className="project-person" key={id}><Avatar person={person}/><div><b>{person?.name||id}</b><div className="row-meta">{person?.role||"Team member"} · {person?.department||"—"}</div></div></div>})}</section><section className="panel detail-section"><h3>Resources</h3>{project.resources.length?project.resources.map(resource=><div className="resource-row" key={resource.id}>{resource.kind==="image"?<Image size={14}/>:<FileText size={14}/>}<span>{resource.name}</span></div>):<div className="row-meta">No resources uploaded.</div>}</section></aside></div></div>
}
 function TaskDetail({task,user,can,update,onBack,onReport}:{task:Task;user:User;can:(x:string)=>boolean;update:(id:string,p:Partial<Task>)=>void;onBack:()=>void;onReport:()=>void}){const mine=task.assignee===user.id;const approvalBlocked=Boolean(task.pr&&!task.merged);return <div className="task-detail"><button className="btn" onClick={onBack}><ArrowLeft size={14}/> Back to tasks</button><div style={{marginTop:22}}><div className="eyebrow">{task.id} / {task.project} / {task.department}</div><h1 className="title">{task.title}</h1><div className="inline" style={{marginTop:11}}><Status s={task.status}/><span className="muted">Due {task.due} · Target {task.targetWeek}</span></div></div><div className="detail-grid section-gap"><div className="panel detail-section"><h3>What good looks like</h3><p style={{fontSize:13,lineHeight:1.6,color:"#596660"}}>{task.description}</p><ul className="criteria">{task.criteria.map((c,i)=><li key={c}><Check size={14} color="#56816d" style={{verticalAlign:"middle",marginRight:8}}/>Acceptance criterion {i+1}: {c}</li>)}</ul>{task.pr&&<div className="notice" style={{marginTop:18}}><GitPullRequest size={14} style={{verticalAlign:"middle",marginRight:7}}/>PR evidence linked: <span className="mono">{task.pr}</span>{task.merged?" · Merged":" · Open"}</div>}{task.blocker&&<div className="notice" style={{marginTop:18,borderColor:"#b46c5c",background:"#fbefeb"}}><AlertTriangle size={14} style={{verticalAlign:"middle",marginRight:7}}/>Blocker: {task.blocker.reason}<br/><small>Need: {task.blocker.need} · Waiting for: {task.blocker.waitingFor} · Severity: {task.blocker.severity}</small></div>}<div className="section-gap"><h3>Operational detail</h3><div className="row-meta">Created {task.createdDate} by {users.find(u=>u.id===task.createdBy)?.name||"System"} · {task.attachments?.join(", ")||"No attachments"}</div></div></div><div className="panel detail-section"><h3>Ownership</h3><div className="row"><span className="muted">Assignee</span><b>{task.assignee?users.find(u=>u.id===task.assignee)?.name:"Available"}</b></div><div className="row"><span className="muted">Priority</span><b>{task.priority}</b></div><div className="row"><span className="muted">Review</span><b>{task.reviewState}</b></div><div className="form-grid" style={{marginTop:18}}>{!task.assignee&&(task.available||task.status==="Available")&&<button className="btn primary" onClick={()=>update(task.id,{assignee:user.id,status:"Assigned",available:false})}>Claim task</button>}{mine&&(task.status==="Inbox"||task.status==="Planned"||task.status==="Assigned")&&<button className="btn primary" onClick={()=>update(task.id,{status:"In Progress",startDate:"2026-09-16"})}>Start task</button>}{mine&&task.status!=="Done"&&task.status!=="Cancelled"&&<button className="btn" onClick={()=>update(task.id,{status:"In Review",reviewState:"Awaiting review",pr:task.pr||"https://github.com/olyxee/repo/pull/new"})}>Submit PR for review</button>}{task.status==="In Review"&&task.pr&&!task.merged&&can("review")&&<button className="btn" onClick={()=>update(task.id,{merged:true,status:"In Review"})}>Mark PR merged</button>}{task.status==="In Review"&&can("review")&&<><button className="btn primary" disabled={approvalBlocked} title={approvalBlocked?"Mark the PR merged before approving this task.":undefined} onClick={()=>update(task.id,{status:"Done",reviewState:"Approved"})}>Approve and mark done</button><button className="btn" onClick={()=>update(task.id,{status:"In Progress",reviewState:"Changes requested"})}>Request changes</button></>}{mine&&task.status!=="Blocked"&&task.status!=="Done"&&<button className="btn danger" onClick={onReport}>Report blocker</button>}{task.status==="Blocked"&&can("review")&&<button className="btn primary" onClick={()=>update(task.id,{status:"In Progress",blocker:undefined})}>Resolve blocker</button>}</div></div></div></div>}
  function TaskModal({onClose,onSave,user,team,projectNames}:{onClose:()=>void;onSave:(t:Task)=>void;user:User;team:User[];projectNames:string[]}){const [title,setTitle]=useState("");const [project,setProject]=useState(projectNames[0]||projects[0]);const [department,setDepartment]=useState(user.role==="Manager"?user.department:"AI Engineering");const [assignee,setAssignee]=useState("");const [desc,setDesc]=useState("");const [priority,setPriority]=useState<Task["priority"]>("Medium");const [due,setDue]=useState("2026-09-18");const [available,setAvailable]=useState(false);const [commit,setCommit]=useState(true);const [file,setFile]=useState("");const people=team.filter(u=>u.active!==false&&u.role==="Intern"&&u.department===department&&(user.role==="Super Admin"||u.reportsTo===user.id));return <Modal title="Create task" onClose={onClose} footer={<><button className="btn" onClick={onClose}>Cancel</button><button className="btn primary" disabled={!title.trim()} onClick={()=>onSave({id:"",title,project,department,createdBy:user.id,status:available?"Available":"Planned",assignee:available?undefined:assignee||undefined,priority,due,createdDate:"2026-09-16",targetWeek:"14–18 Sep 2026",description:desc||"Define the desired outcome and evidence for this task.",criteria:["Acceptance criteria are agreed","Evidence is attached before review"],dependencies:[],comments:[],activity:["Created from quick capture"],attachments:file?[file]:[],weeklyCommitment:commit,available})}>Create task</button></>}><div className="form-grid"><label className="form-label">Task name<input className="input" value={title} onChange={e=>setTitle(e.target.value)} placeholder="e.g. Orgni parser tests"/></label><label className="form-label">Description<textarea className="textarea" rows={3} value={desc} onChange={e=>setDesc(e.target.value)} placeholder="What outcome should this produce?"/></label><label className="form-label">Project<select className="select" value={project} onChange={e=>setProject(e.target.value)}>{projectNames.map(x=><option key={x}>{x}</option>)}</select></label><label className="form-label">Department<select className="select" value={department} onChange={e=>setDepartment(e.target.value)} disabled={user.role==="Manager"}>{["AI Engineering","Product Engineering","Data","Operations"].map(x=><option key={x}>{x}</option>)}</select></label><label className="form-label">Priority<select className="select" value={priority} onChange={e=>{setPriority(e.target.value as Task["priority"]);if(e.target.value==="Critical")setAvailable(false)}}>{["Critical","High","Medium","Low"].map(x=><option key={x}>{x}</option>)}</select></label><label className="form-label">Due date<input className="input" type="date" value={due} onChange={e=>setDue(e.target.value)}/></label><label className="form-label">Assignee<select className="select" value={assignee} onChange={e=>setAssignee(e.target.value)}><option value="">Unassigned</option>{people.map(u=><option key={u.id} value={u.id}>{u.name}</option>)}</select></label><label className="inline" style={{fontSize:12}}><input type="checkbox" checked={available} disabled={priority==="Critical"} onChange={e=>setAvailable(e.target.checked)}/> Available Work</label><label className="inline" style={{fontSize:12}}><input type="checkbox" checked={commit} onChange={e=>setCommit(e.target.checked)}/> Weekly commitment</label><label className="form-label">Screenshot attachment<input className="input" type="file" accept="image/*" onChange={e=>setFile(e.target.files?.[0]?.name||"")}/>{file&&<span className="row-meta">Saved filename: {file}</span>}</label></div></Modal>}
  function ProjectModal({team,onClose,onSave}:{team:User[];onClose:()=>void;onSave:(project:Omit<Project,"id">)=>void}){const [name,setName]=useState("");const [description,setDescription]=useState("");const [githubUrl,setGithubUrl]=useState("");const [logoUrl,setLogoUrl]=useState("");const [assigneeIds,setAssigneeIds]=useState<string[]>([]);const [resources,setResources]=useState<{name:string;kind:"document"|"image"}[]>([]);const people=team.filter(u=>u.active!==false&&(u.role==="Manager"||u.role==="Intern"));const validUrl=/^https?:\/\/(www\.)?github\.com\/.+/i.test(githubUrl.trim());const readLogo=(file?:File)=>{if(!file)return;const reader=new FileReader();reader.onload=()=>setLogoUrl(String(reader.result));reader.readAsDataURL(file)};return <Modal title="Create project" onClose={onClose} footer={<><button className="btn" onClick={onClose}>Cancel</button><button className="btn primary" disabled={!name.trim()||!validUrl} onClick={()=>onSave({name:name.trim(),description:description.trim()||"Project workspace",githubUrl:githubUrl.trim(),logoUrl:logoUrl||undefined,assigneeIds,resources:resources.map(resource=>({...resource,id:crypto.randomUUID()})),active:true,status:"Active"})}>Create project</button></>}><div className="form-grid"><label className="form-label">Project name<input className="input" value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Customer onboarding"/></label><label className="form-label">Description<textarea className="textarea" rows={3} value={description} onChange={e=>setDescription(e.target.value)} placeholder="What outcome does this project deliver?"/></label><label className="form-label">Project logo<input className="input" type="file" accept="image/*" onChange={e=>readLogo(e.target.files?.[0])}/>{logoUrl&&<img className="project-logo-preview" src={logoUrl} alt="Project logo preview"/>}</label><label className="form-label">GitHub repository URL<input className="input" type="url" value={githubUrl} onChange={e=>setGithubUrl(e.target.value)} placeholder="https://github.com/olyxee/repository"/>{githubUrl&&!validUrl&&<span style={{color:"#9a453d"}}>Enter a valid GitHub URL.</span>}</label><div className="form-label">Assign managers and interns<div className="list" style={{padding:"4px 0"}}>{people.map(person=><label className="inline" style={{fontSize:12,padding:"5px 0"}} key={person.id}><input type="checkbox" checked={assigneeIds.includes(person.id)} onChange={e=>setAssigneeIds(ids=>e.target.checked?[...ids,person.id]:ids.filter(id=>id!==person.id))}/><span>{person.name} <span className="muted">· {person.role}</span></span></label>)}</div></div><label className="form-label">Project resources<input className="input" type="file" multiple accept="image/*,.pdf,.doc,.docx,.txt,.md" onChange={e=>setResources(Array.from(e.target.files||[]).map(file=>({name:file.name,kind:file.type.startsWith("image/")?"image":"document"})))}/>{resources.length>0&&<span className="row-meta">{resources.map(resource=>resource.name).join(" · ")}</span>}</label></div></Modal>}
 function PersonModal({user,team,person,onClose,onSave}:{user:User;team:User[];person?:User;onClose:()=>void;onSave:(person:User)=>void}){
  const administrator=isAdmin(user); const editing=Boolean(person);
  const [name,setName]=useState(person?.name||""); const [email,setEmail]=useState(person?.email||""); const [department,setDepartment]=useState(person?.department||(isManager(user)?user.department:"AI Engineering"));
  const [employmentType,setEmploymentType]=useState<EmploymentType>(person?employmentOf(person):isManager(user)?"Intern":"Employee");
  const [accessRole,setAccessRole]=useState<AccessRole>(person?accessOf(person):isManager(user)?"Member":"Member");
  const [accountStatus,setAccountStatus]=useState<AccountStatus>(person?accountOf(person):"Pending");
  const [reportsTo,setReportsTo]=useState(person?.reportsTo||(isManager(user)?user.id:"u1"));
  const emailValid=email.endsWith("@olyxee.com"); const managers=team.filter(member=>isManager(member)&&accountOf(member)==="Active");
  const accessOptions:AccessRole[]=administrator?["Superadmin","Admin","Manager","Member"]:["Member"];
  return <Modal title={editing?"Manage team member":"Add team member"} onClose={onClose} footer={<><button className="btn" onClick={onClose}>Cancel</button><button className="btn primary" disabled={!name.trim()||!emailValid} onClick={()=>onSave({...person,id:person?.id||"",name,email,department,employmentType,accessRole,accountStatus,reportsTo} as User)}>{editing?"Save changes":"Add person"}</button></>}>
    <div className="form-grid"><label className="form-label">Full name<input className="input" value={name} onChange={e=>setName(e.target.value)} placeholder="Full name"/></label><label className="form-label">Company email<input className="input" value={email} onChange={e=>setEmail(e.target.value)} placeholder="name@olyxee.com"/>{email&&!emailValid&&<span style={{color:"#9a453d"}}>Use an approved @olyxee.com address.</span>}</label><label className="form-label">Department<select className="select" value={department} disabled={!administrator} onChange={e=>setDepartment(e.target.value)}>{["AI Engineering","Product Engineering","Data","Operations"].map(x=><option key={x}>{x}</option>)}</select></label><label className="form-label">Employment type<select className="select" value={employmentType} disabled={!administrator} onChange={e=>setEmploymentType(e.target.value as EmploymentType)}>{["Employee","Intern"].map(x=><option key={x}>{x}</option>)}</select></label><label className="form-label">Access role<select className="select" value={accessRole} disabled={!administrator} onChange={e=>setAccessRole(e.target.value as AccessRole)}>{accessOptions.map(x=><option key={x}>{x}</option>)}</select></label><label className="form-label">Account status<select className="select" value={accountStatus} onChange={e=>setAccountStatus(e.target.value as AccountStatus)}>{["Active","Pending","Suspended"].map(x=><option key={x}>{x}</option>)}</select></label>{accessRole==="Member"&&<label className="form-label">Manager<select className="select" value={reportsTo} disabled={!administrator} onChange={e=>setReportsTo(e.target.value)}>{managers.filter(manager=>administrator||manager.id===user.id).map(manager=><option key={manager.id} value={manager.id}>{manager.name}</option>)}</select></label>}<div className="notice">{administrator?"Employment type, access permissions, and account status are managed independently.":"Managers can add members within their own department and manage their account status."}</div></div>
  </Modal>
 }
function BlockerModal({onClose,onSave}:{onClose:()=>void;onSave:(b:{reason:string;need:string;waitingFor:string;severity:"Low"|"Medium"|"High"|"Critical"})=>void}){const [reason,setReason]=useState("");const [need,setNeed]=useState("");const [waitingFor,setWaitingFor]=useState("");const [severity,setSeverity]=useState<"Low"|"Medium"|"High"|"Critical">("Medium");return <Modal title="Report blocker" onClose={onClose} footer={<><button className="btn" onClick={onClose}>Cancel</button><button className="btn danger" disabled={!reason||!need||!waitingFor} onClick={()=>onSave({reason,need,waitingFor,severity})}>Report blocker</button></>}><div className="form-grid"><label className="form-label">What is blocking you?<textarea className="textarea" rows={3} value={reason} onChange={e=>setReason(e.target.value)} placeholder="Describe the constraint clearly."/></label><label className="form-label">What do you need?<input className="input" value={need} onChange={e=>setNeed(e.target.value)} placeholder="Access, decision, dependency, clarification..."/></label><label className="form-label">Who or what are you waiting for?<input className="input" value={waitingFor} onChange={e=>setWaitingFor(e.target.value)} placeholder="Team, person, or external dependency"/></label><label className="form-label">Severity<select className="select" value={severity} onChange={e=>setSeverity(e.target.value as typeof severity)}>{["Low","Medium","High","Critical"].map(x=><option key={x}>{x}</option>)}</select></label></div></Modal>}
function Modal({title,onClose,children,footer,className=""}:{title:React.ReactNode;onClose:()=>void;children:React.ReactNode;footer:React.ReactNode;className?:string}){return <div className="modal-back" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><div className={`modal ${className}`}><div className="modal-head"><b>{title}</b><button className="close" onClick={onClose}><X size={18}/></button></div><div className="modal-body">{children}</div><div className="modal-foot">{footer}</div></div></div>}
function SettingsModal({user,team,setTeam,statuses,setStatuses,tasks,flash,onClose}:{user:User;team:User[];setTeam:React.Dispatch<React.SetStateAction<User[]>>;statuses:StaffStatus[];setStatuses:React.Dispatch<React.SetStateAction<StaffStatus[]>>;tasks:Task[];flash:(s:string)=>void;onClose:()=>void}){
   const [tab,setTab]=useState<"Workspace"|"Status"|"Profile">("Profile");
  const current=statuses.find(s=>s.userId===user.id)||{userId:user.id,availability:"Available" as Availability,start:"09:00",end:"17:30",note:"",updatedAt:""};
  const [availability,setAvailability]=useState<Availability>(current.availability); const [start,setStart]=useState(current.start); const [end,setEnd]=useState(current.end); const [note,setNote]=useState(current.note);
  const [avatarUrl,setAvatarUrl]=useState(user.avatarUrl||""); const [email,setEmail]=useState(user.email); const [contactDetails,setContactDetails]=useState(user.contactDetails||""); const [githubUsername,setGithubUsername]=useState(user.githubUsername||"");
  const emailValid=/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email.trim()); const githubValid=!githubUsername.trim()||/^[a-z\d](?:[a-z\d-]{0,37}[a-z\d])?$/i.test(githubUsername.trim());
   const saveStatus=()=>{setStatuses(all=>[...all.filter(s=>s.userId!==user.id),{userId:user.id,availability,start,end,note,updatedAt:"Just now"}]);flash("Status updated");onClose()};
   const saveProfile=()=>{if(!emailValid||!githubValid)return;setTeam(all=>all.map(person=>person.id===user.id?{...person,email:email.trim(),contactDetails:contactDetails.trim()||undefined,githubUsername:githubUsername.trim()||undefined,avatarUrl:avatarUrl||undefined}:person));flash("Profile updated");onClose()};
  const readImage=(file?:File)=>{if(!file)return;const reader=new FileReader();reader.onload=()=>setAvatarUrl(String(reader.result));reader.readAsDataURL(file)};
    const nav=[{id:"Profile" as const,label:"Profile",detail:"Photo and contact details",icon:UserRound},{id:"Status" as const,label:"Work status",detail:"Availability and hours",icon:Clock3},{id:"Workspace" as const,label:"Workspace",detail:"Week and local data",icon:LayoutDashboard}];
    return <Modal className="settings-dialog" title={<span className="settings-modal-title"><Settings size={18}/><span>Settings</span></span>} onClose={onClose} footer={<><button className="btn" onClick={onClose}>Close</button>{tab==="Status"&&<button className="btn primary" onClick={saveStatus}>Save status</button>}{tab==="Profile"&&<button className="btn primary" disabled={!emailValid||!githubValid} onClick={saveProfile}>Save profile</button>}</>}>
     <div className="settings-layout">
        <aside className="settings-sidebar">{nav.map(item=>{const Icon=item.icon;return <button className={tab===item.id?"active":""} onClick={()=>setTab(item.id)} key={item.id}><span className="settings-tab-icon"><Icon size={17}/></span><span className="settings-tab-copy"><b>{item.label}</b><small>{item.detail}</small></span><ChevronRight className="settings-tab-chevron" size={14}/></button>})}</aside>
       <section className="settings-panel">
          <div className="settings-panel-content" key={tab}>
         {tab==="Profile"?<><div className="settings-section-head"><div><div className="eyebrow">Personal profile</div><h3>Profile details</h3><p>Your details appear across projects, staff views, and assignments.</p></div></div><div className="settings-group profile-photo-row"><Avatar person={{...user,avatarUrl}} size={64}/><div><b>{user.name}</b><span>{employmentOf(user)} · {accessOf(user)} · {user.department}</span><label className="profile-photo-action">Change photo<input type="file" accept="image/*" onChange={e=>readImage(e.target.files?.[0])}/></label>{avatarUrl&&<button type="button" onClick={()=>setAvatarUrl("")}>Remove</button>}</div></div><div className="settings-group settings-fields"><label>Full name<span className="locked-field"><input value={user.name} readOnly/><small>Managed by your workspace administrator</small></span></label><label>Email address<span><input type="email" value={email} onChange={e=>setEmail(e.target.value)}/>{email&&!emailValid&&<small className="field-error">Enter a valid email address</small>}</span></label><label>Contact number<span><input value={contactDetails} onChange={e=>setContactDetails(e.target.value)} placeholder="+27 00 000 0000"/></span></label><label>GitHub username<span className="input-prefix"><i>@</i><input value={githubUsername} onChange={e=>setGithubUsername(e.target.value)} placeholder="username"/></span>{githubUsername&&!githubValid&&<small className="field-error">Enter a valid GitHub username</small>}</label></div></>:tab==="Status"?<><div className="settings-section-head"><div><div className="eyebrow">Work presence</div><h3>Status and hours</h3><p>This is visible to your manager and administrators.</p></div></div><div className="settings-group settings-fields"><label>Availability<span><select value={availability} onChange={e=>setAvailability(e.target.value as Availability)}>{["Available","Busy","Offline"].map(x=><option key={x}>{x}</option>)}</select></span></label><label>Working hours<span className="settings-time-pair"><input type="time" value={start} onChange={e=>setStart(e.target.value)}/><em>to</em><input type="time" value={end} onChange={e=>setEnd(e.target.value)}/></span></label><label>Current focus<span><textarea rows={3} maxLength={120} value={note} onChange={e=>setNote(e.target.value)} placeholder="What are you focused on?"/></span></label></div></>:<><div className="settings-section-head"><div><div className="eyebrow">Workspace controls</div><h3>Demo workspace</h3><p>Manage the current operating week and locally stored demo data.</p></div></div><div className="settings-group settings-list"><div><span><b>Current operating week</b><small>14–18 September 2026 · Week 38</small></span><span className="badge green">Active</span></div><div><span><b>Data storage</b><small>Browser localStorage · {tasks.length} tasks persisted</small></span><span className="badge gray">Local only</span></div></div><div className="settings-danger"><b>Reset demo data</b><p>Remove browser changes and return this workspace to its original sample data.</p><button className="btn danger" onClick={()=>{localStorage.clear();flash("Demo data reset");window.location.reload()}}>Reset demo data</button></div></>}
          </div>
       </section>
     </div>
  </Modal>
}
function Review({tasks,objectives,team,user,onOpen,onNewObjective,update,setObjectives,can,flash}:{tasks:Task[];objectives:WeeklyObjective[];team:User[];user:User;onOpen:(id:string)=>void;onNewObjective:()=>void;update:(id:string,p:Partial<Task>)=>void;setObjectives:React.Dispatch<React.SetStateAction<WeeklyObjective[]>>;can:(x:string)=>boolean;flash:(s:string)=>void}){const [decisions,setDecisions]=useState<Record<string,string>>({});const [reasons,setReasons]=useState<Record<string,string>>({});const closeDate="2026-09-18";const visibleObjectives=objectives.filter(o=>user.role==="Super Admin"||o.managerId===user.id);const committed=tasks.filter(t=>t.weeklyCommitment);const delivered=committed.filter(t=>t.status==="Done");const awaitingApproval=committed.filter(t=>t.status==="In Review");const blocked=committed.filter(t=>t.status==="Blocked");const missed=committed.filter(t=>!["Done","In Review","Blocked","Cancelled"].includes(t.status)&&t.due<=closeDate);const discussionCount=blocked.length+awaitingApproval.length+missed.length;const sections=[["BLOCKED COMMITMENTS",blocked,"red"],["AWAITING APPROVAL",awaitingApproval,"amber"],["MISSED COMMITMENTS",missed,"red"]] as const;const owner=(task:Task)=>team.find(u=>u.id===task.assignee)?.name||"Unassigned";const decision=(task:Task,label:string)=>label==="BLOCKED COMMITMENTS"?`Provide ${task.blocker?.need||"the required unblock"} and confirm ownership with ${task.blocker?.waitingFor||"the responsible team"} (severity: ${task.blocker?.severity||"unknown"}).`:label==="AWAITING APPROVAL"?"Approve this work or request changes.":"Choose whether to carry forward, replan, or cancel.";return <><Header eyebrow="Weekly operating cadence" title="Weekly Review" subtitle="Track manager objectives first, then resolve blocked, awaiting, and missed commitments." action={user.role==="Super Admin"&&<button className="btn primary" onClick={onNewObjective}><Plus size={14}/> New objective</button>}/><div className="panel objective-review"><div className="panel-head"><span className="panel-title">Weekly objectives</span><span className="mono">{visibleObjectives.length} tracked</span></div><div className="list">{visibleObjectives.map(o=><div className="row objective-row" key={o.id}><div className="row-main"><div className="row-title">{o.title}</div><div className="row-meta">{user.role==="Super Admin"?team.find(u=>u.id===o.managerId)?.name:"Your objective"} · Due {o.dueDate} · {o.priority} priority</div><div className="row-meta">{o.description}</div></div><div className="inline">{user.role==="Manager"&&o.managerId===user.id?<select className="select" value={o.status} onChange={e=>setObjectives(xs=>xs.map(x=>x.id===o.id?{...x,status:e.target.value as ObjectiveStatus}:x))}>{["Not started","In progress","At risk","Complete"].map(s=><option key={s}>{s}</option>)}</select>:<Status s={o.status}/>}</div></div>)}{!visibleObjectives.length&&<div className="empty">No weekly objectives are assigned to this view.</div>}</div></div><div className="section-gap"><div className="eyebrow">CEO decision agenda</div><div className="grid stats">{[["Delivered",`${delivered.length} / ${committed.length}`],["Decisions needed",discussionCount],["Blocked",blocked.length],["Awaiting approval",awaitingApproval.length]].map(x=><div className="panel stat" key={x[0]}><div className="stat-label">{x[0]}</div><div className="stat-num">{x[1]}</div></div>)}</div><div className="notice" style={{marginBottom:17}}>Week 38 closes Friday, 18 September. Review unresolved commitments below and leave every decision with an owner.</div>{discussionCount===0?<div className="panel empty"><strong>All clear.</strong><br/>No commitments require a decision this week.</div>:<div className="grid">{sections.filter(([,items])=>items.length).map(([label,items,tone])=><div className="panel" key={label}><div className="panel-head"><span className="panel-title">{label}</span><span className={`badge ${tone}`}>{items.length}</span></div><div className="list">{items.map(t=><div className="row" key={t.id} style={{alignItems:"flex-start"}}><div className="row-main"><div className="row-title">{t.title}</div><div className="row-meta">{t.id} · Project: {t.project} · Owner: {owner(t)} · Due: {t.due}</div><div className="row-meta" style={{marginTop:7}}><b>Why discuss:</b> {label==="BLOCKED COMMITMENTS"?t.blocker?.reason||"This commitment is blocked.":label==="AWAITING APPROVAL"?"The work is ready for a review decision.":"The commitment was unfinished by the Friday close."}</div>{label==="MISSED COMMITMENTS"&&<div className="inline" style={{marginTop:12,flexWrap:"wrap"}}><select className="select" value={reasons[t.id]||""} onChange={e=>setReasons(x=>({...x,[t.id]:e.target.value}))}><option value="">Failure reason</option>{["Bad estimation","Unclear requirements","External dependency","Internal dependency","Capacity","Technical issue","Execution issue"].map(x=><option key={x}>{x}</option>)}</select><select className="select" value={decisions[t.id]||""} onChange={e=>setDecisions(x=>({...x,[t.id]:e.target.value}))}><option value="">Next decision</option><option value="carry">Carry Forward</option><option value="replan">Replan</option><option value="cancel">Cancel</option></select><button className="btn" disabled={!reasons[t.id]||!decisions[t.id]||!can("review")} onClick={()=>{update(t.id,{status:decisions[t.id]==="cancel"?"Cancelled":"Planned"});flash("Weekly decision recorded")}}>Record</button></div>}</div><div className="inline"><Status s={t.status}/><button className="btn" onClick={()=>onOpen(t.id)}>Open task</button></div></div>)}</div></div>)}</div>}</div></>}
function ObjectiveModal({managers,onClose,onSave}:{managers:User[];onClose:()=>void;onSave:(o:Omit<WeeklyObjective,"id"|"createdBy"|"createdDate"|"status">)=>void}){const [title,setTitle]=useState("");const [description,setDescription]=useState("");const [managerId,setManagerId]=useState(managers[0]?.id||"");const [priority,setPriority]=useState<WeeklyObjective["priority"]>("High");const [dueDate,setDueDate]=useState("2026-09-18");return <Modal title="Create weekly objective" onClose={onClose} footer={<><button className="btn" onClick={onClose}>Cancel</button><button className="btn primary" disabled={!title.trim()||!managerId} onClick={()=>onSave({title,description:description||"Define the intended outcome for this objective.",managerId,priority,dueDate})}>Create objective</button></>}><div className="form-grid"><label className="form-label">Objective title<input className="input" value={title} onChange={e=>setTitle(e.target.value)}/></label><label className="form-label">Description / outcome<textarea className="textarea" rows={3} value={description} onChange={e=>setDescription(e.target.value)}/></label><label className="form-label">Assigned manager<select className="select" value={managerId} onChange={e=>setManagerId(e.target.value)}>{managers.map(m=><option key={m.id} value={m.id}>{m.name} · {m.department}</option>)}</select></label><label className="form-label">Priority<select className="select" value={priority} onChange={e=>setPriority(e.target.value as WeeklyObjective["priority"])}>{["Critical","High","Medium","Low"].map(x=><option key={x}>{x}</option>)}</select></label><label className="form-label">Due date<input className="input" type="date" value={dueDate} onChange={e=>setDueDate(e.target.value)}/></label></div></Modal>}
function SettingsView({tasks,setTasks,flash}:{tasks:Task[];setTasks:React.Dispatch<React.SetStateAction<Task[]>>;flash:(s:string)=>void}){return <><Header eyebrow="Workspace controls" title="Settings" subtitle="Demo configuration and local workspace maintenance."/><div className="panel detail-section" style={{maxWidth:680}}><h3>Demo workspace</h3><div className="row"><div><b>Current operating week</b><div className="row-meta">14–18 September 2026 · Week 38</div></div><span className="badge green">Active</span></div><div className="row"><div><b>Data storage</b><div className="row-meta">Browser localStorage · {tasks.length} tasks persisted</div></div><span className="badge gray">Local only</span></div><div style={{marginTop:22}}><button className="btn danger" onClick={()=>{localStorage.clear();flash("Demo data reset");window.location.reload()}}>Reset demo data</button></div></div></>}